请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-003

=== 用户原始指令 (query.txt) ===
弄个通知列表那种，数字会跳，点开跳app，日程拉一下，状态显示已完成哈

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个通知列表那种，数字会跳，点开跳app，日程拉一下，状态显示已完成哈",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "当天日程通知列表",
          "sampleValue": [
            {
              "entityName": "calendar",
              "entityId": "event-001",
              "title": "产品评审",
              "dtStart": "09:30",
              "dtEnd": "10:00"
            },
            {
              "entityName": "calendar",
              "entityId": "event-002",
              "title": "设计同步",
              "dtStart": "11:00",
              "dtEnd": "11:30"
            },
            {
              "entityName": "calendar",
              "entityId": "event-003",
              "title": "复盘整理",
              "dtStart": "16:00",
              "dtEnd": "16:30"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日程通知",
            "properties": {
              "entityName": {
                "type": "string",
                "description": "日程实体类别",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "event-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "产品评审"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间",
                "sampleValue": "09:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间",
                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    },
    "state": {
      "notificationCount": {
        "type": "integer",
        "description": "聚合通知数量",
        "sampleValue": 3
      },
      "statusText": {
        "type": "string",
        "description": "当前处理状态",
        "sampleValue": "已完成"
      },
      "loading": {
        "type": "boolean",
        "description": "日程数据加载态",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": []
}

